input.old_string:
p.sub { color: #a8adb5; margin: 0 0 32px; font-size: 15px; line-height: 1.6 }
.card { border: 1px solid #e8eaee; border-radius: 12px; padding: 28px; max-width: 380px }
.plan { font-size: 13px; letter-spacing: 0.08em; text-transform: uppercase; color: #b9bec6 }
.price { font-size: 34px; font-weight: 700; margin: 10px 0 }
.price small { font-size: 14px; font-weight: 400; color: #b0b5bd }
ul { padding-left: 18px; margin: 0 0 24px; color: #9aa0a8; font-size: 14px; line-height: 1.9 }
a.more { color: #9db9f2; font-size: 14px }
button { width: 100%; padding: 12px; background: #86a9ef; color: #ffffff; border: 0; border-radius: 8px; font-size: 15px; font-weight: 600; cursor: pointer; margin-bottom: 14px }
.note { font-size: 12px; color: #bcc1c8; margin-top: 20px }

